<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, apiMessage, type ProjectSummary } from '@/api'
import { districtsOf, normalizeDistrict, provinces } from '@/data/cities'

const router = useRouter(); const projects = ref<ProjectSummary[]>([]); const loading = ref(true); const saving = ref(false); const dialog = ref(false); const pageError = ref('')
const cityOptions = computed(() => districtsOf(form.province))
function syncDistrict() { form.cityDistrict = normalizeDistrict(form.province, form.cityDistrict) }
const form = reactive({ projectName: '', buildingArea: 0, province: '', cityDistrict: '', address: '', buildingType: '', structureType: '', floorCount: '', designLife: '', startDate: '', plannedCompletionDate: '', projectManager: '', accountingStandard: 'GB/T 51366-2019' })
async function load() { loading.value = true; pageError.value = ''; try { projects.value = (await api.get('/projects')).data } catch (error) { pageError.value = apiMessage(error, '项目列表加载失败') } finally { loading.value = false } }
function openCreate() { Object.assign(form, { projectName: '', buildingArea: 0, province: '', cityDistrict: '', address: '', buildingType: '', structureType: '', floorCount: '', designLife: '', startDate: '', plannedCompletionDate: '', projectManager: '', accountingStandard: 'GB/T 51366-2019' }); dialog.value = true }
async function create() { if (!form.projectName.trim() || !(form.buildingArea > 0)) { ElMessage.warning('请填写项目名称和大于 0 的建筑面积'); return }; saving.value = true; try { await api.post('/projects', form); dialog.value = false; ElMessage.success('项目已创建'); await load() } catch (error) { ElMessage.error(apiMessage(error, '项目创建失败')) } finally { saving.value = false } }
async function remove(project: ProjectSummary) { try { await ElMessageBox.confirm(`确定永久删除“${project.projectName}”？此操作不可恢复。`, '删除项目', { type: 'warning' }); await api.delete(`/projects/${project.id}`); ElMessage.success('项目已删除'); await load() } catch (error: any) { if (error !== 'cancel' && error !== 'close') ElMessage.error(apiMessage(error, '项目删除失败')) } }
onMounted(load)
</script>
<template>
  <div class="content-wrap"><div class="page-heading"><div><div class="eyebrow">项目台账</div><h1>我的项目</h1><p class="muted">管理项目基础信息、核算记录和历史版本</p></div><el-button type="primary" class="primary-button" @click="openCreate">＋ 新建项目</el-button></div><el-alert v-if="pageError" :title="pageError" type="error" show-icon :closable="false" class="project-load-error"><template #default><el-button link type="primary" @click="load">重试</el-button></template></el-alert>
    <div v-loading="loading" class="project-grid"><article v-for="project in projects" :key="project.id" class="project-card" @click="router.push(`/projects/${project.id}`)"><div class="project-card-top"><span class="project-status">核算中</span><el-dropdown @click.stop><el-button text class="more-button">•••</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="router.push(`/projects/${project.id}/tools`)">因子配置</el-dropdown-item><el-dropdown-item @click="router.push(`/projects/${project.id}/tools?tab=versions`)">核算版本与报告</el-dropdown-item><el-dropdown-item @click="remove(project)">永久删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><h3>{{ project.projectName }}</h3><p class="project-location">{{ [project.province, project.cityDistrict].filter(Boolean).join(' · ') || '未填写项目地点' }}</p><div class="project-metrics"><div><strong>{{ Number(project.buildingArea || 0).toLocaleString() }}</strong><span>建筑面积 / ㎡</span></div><div><strong>{{ project.recordCounts?.buildMaterials || 0 }}</strong><span>建材记录</span></div><div><strong>v{{ project.latestVersion?.versionNumber || 0 }}</strong><span>最新版本</span></div></div><div class="project-card-foot"><span>最近更新 {{ new Date(project.updatedAt).toLocaleDateString() }}</span><span class="arrow">→</span></div></article><div v-if="!loading && projects.length === 0" class="empty-state"><div class="empty-icon">+</div><h3>还没有项目</h3><p>创建第一个项目，开始记录碳排放数据。</p><el-button type="primary" @click="openCreate">新建项目</el-button></div></div>
    <el-dialog v-model="dialog" title="新建项目" width="620px"><el-form label-position="top"><el-form-item label="项目名称" required><el-input v-model="form.projectName" placeholder="例如：中心大厦 A 座建设工程" /></el-form-item><div class="form-grid"><el-form-item label="建筑面积（㎡）" required><el-input-number v-model="form.buildingArea" :min="0.000001" :controls="false" class="full-width" /></el-form-item><el-form-item label="建筑类型"><el-select v-model="form.buildingType"><el-option label="商业综合体" value="商业综合体"/><el-option label="住宅" value="住宅"/><el-option label="公共建筑" value="公共建筑"/></el-select></el-form-item><el-form-item label="省份"><el-select v-model="form.province" filterable placeholder="选择省份" @change="syncDistrict"><el-option v-for="item in provinces" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="城市/区县"><el-select v-model="form.cityDistrict" filterable placeholder="先选择省份"><el-option v-for="item in cityOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="结构类型"><el-input v-model="form.structureType" /></el-form-item><el-form-item label="楼层数"><el-input v-model="form.floorCount" /></el-form-item><el-form-item label="设计使用年限"><el-input v-model="form.designLife" /></el-form-item><el-form-item label="项目负责人"><el-input v-model="form.projectManager" /></el-form-item><el-form-item label="开工日期"><el-input v-model="form.startDate" type="date" /></el-form-item><el-form-item label="计划竣工日期"><el-input v-model="form.plannedCompletionDate" type="date" /></el-form-item></div><el-form-item label="项目地址"><el-input v-model="form.address" /></el-form-item><el-form-item label="核算标准"><el-input v-model="form.accountingStandard" /></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建项目</el-button></template></el-dialog>
  </div>
</template>
